/* Kakeibo · materi bunpou JLPT N5–N1 (lokal, gratis, tanpa API). 76 pola, penjelasan dan contoh ditulis asli untuk app ini dalam bahasa Indonesia dan Inggris.
 * Bahasa lain otomatis memakai teks Inggris. Format: f = cara membentuk, m = arti, e = penjelasan, x = contoh {jp, r (cara baca), m}, n = catatan. */
window.JLPT_GRAMMAR = {"g_wa_desu":{"f":"N1 は N2 です","m":{"id":"Penanda topik は dan kopula です: 'X adalah Y'","en":"Topic marker は and copula です: 'X is Y'"},"e":{"id":"は menandai topik pembicaraan (dibaca 'wa'), です membuat kalimat sopan. Negatifnya ～ではありません / ～じゃありません.","en":"は marks the topic (read 'wa') and です makes the sentence polite. The negative is ～ではありません / ～じゃありません."},"x":[{"jp":"私はインドネシア人です。","r":"わたしはインドネシアじんです。","m":{"id":"Saya orang Indonesia.","en":"I am Indonesian."}},{"jp":"これはペンです。","r":"これはペンです。","m":{"id":"Ini pena.","en":"This is a pen."}},{"jp":"田中さんは先生ではありません。","r":"たなかさんはせんせいではありません。","m":{"id":"Pak Tanaka bukan guru.","en":"Mr. Tanaka is not a teacher."}}]},"g_ka_no":{"f":"文 + か ／ N1 の N2","m":{"id":"か membuat pertanyaan, の menyambung benda (kepemilikan)","en":"か makes a question; の links nouns (possession)"},"e":{"id":"Tambahkan か di akhir kalimat untuk bertanya. の menyambung dua kata benda: 'N2 milik N1' atau 'N2 tentang N1'.","en":"Add か at the end of a sentence to ask a question. の links two nouns: 'N1's N2' or 'N2 about N1'."},"x":[{"jp":"あなたは学生ですか。","r":"あなたはがくせいですか。","m":{"id":"Apakah kamu pelajar?","en":"Are you a student?"}},{"jp":"これは私の本です。","r":"これはわたしのほんです。","m":{"id":"Ini buku saya.","en":"This is my book."}},{"jp":"日本語の先生はどこですか。","r":"にほんごのせんせいはどこですか。","m":{"id":"Di mana guru bahasa Jepang?","en":"Where is the Japanese teacher?"}}]},"g_wo":{"f":"N を V","m":{"id":"Penanda objek langsung を (dibaca 'o')","en":"Direct object marker を (read 'o')"},"e":{"id":"を menempel pada benda yang dikenai tindakan kata kerja.","en":"を attaches to the thing that the verb acts on."},"x":[{"jp":"パンを食べます。","r":"パンをたべます。","m":{"id":"Saya makan roti.","en":"I eat bread."}},{"jp":"水を飲みますか。","r":"みずをのみますか。","m":{"id":"Apakah kamu minum air?","en":"Do you drink water?"}},{"jp":"毎日日本語を勉強します。","r":"まいにちにほんごをべんきょうします。","m":{"id":"Setiap hari saya belajar bahasa Jepang.","en":"I study Japanese every day."}}]},"g_ni_he":{"f":"N + に／へ + V","m":{"id":"に/へ menunjukkan arah dan tujuan; に juga menandai waktu tertentu","en":"に/へ mark direction and destination; に also marks a specific time"},"e":{"id":"へ (dibaca 'e') dan に dipakai untuk tujuan setelah kata kerja gerak seperti いきます. に juga menandai jam atau tanggal tertentu: 7時に.","en":"へ (read 'e') and に mark the destination of motion verbs such as いきます. に also marks a specific time: 7時に."},"x":[{"jp":"学校へ行きます。","r":"がっこうへいきます。","m":{"id":"Saya pergi ke sekolah.","en":"I go to school."}},{"jp":"七時に起きます。","r":"しちじにおきます。","m":{"id":"Saya bangun jam 7.","en":"I get up at 7 o'clock."}},{"jp":"友だちに会います。","r":"ともだちにあいます。","m":{"id":"Saya bertemu teman.","en":"I meet a friend."}}]},"g_de":{"f":"N + で + V","m":{"id":"で: tempat melakukan kegiatan, serta alat atau cara","en":"で: place of an action, and means or tool"},"e":{"id":"で menunjukkan di mana tindakan berlangsung, atau dengan apa/cara apa dilakukan. Beda dengan に yang menunjukkan tempat keberadaan.","en":"で shows where an action takes place or what means is used. It differs from に, which marks where something exists."},"x":[{"jp":"図書館で勉強します。","r":"としょかんでべんきょうします。","m":{"id":"Saya belajar di perpustakaan.","en":"I study at the library."}},{"jp":"電車で会社へ行きます。","r":"でんしゃでかいしゃへいきます。","m":{"id":"Saya ke kantor naik kereta.","en":"I go to the office by train."}},{"jp":"はしでご飯を食べます。","r":"はしでごはんをたべます。","m":{"id":"Saya makan nasi pakai sumpit.","en":"I eat rice with chopsticks."}}]},"g_masu":{"f":"V語幹 + ます / ません","m":{"id":"Kata kerja sopan: sekarang/akan datang dan negatifnya","en":"Polite verb: present/future and its negative"},"e":{"id":"Ganti akhiran bentuk kamus dengan ます (bentuk i dulu untuk kata kerja u): たべる→たべます, のむ→のみます. Negatif: ません. Untuk kebiasaan dan rencana.","en":"Attach ます to the stem (i-form for u-verbs): たべる→たべます, のむ→のみます. Negative: ません. Used for habits and future plans."},"x":[{"jp":"毎朝コーヒーを飲みます。","r":"まいあさコーヒーをのみます。","m":{"id":"Tiap pagi saya minum kopi.","en":"I drink coffee every morning."}},{"jp":"あした学校へ行きません。","r":"あしたがっこうへいきません。","m":{"id":"Besok saya tidak pergi ke sekolah.","en":"I won't go to school tomorrow."}},{"jp":"テレビを見ますか。","r":"テレビをみますか。","m":{"id":"Apakah kamu menonton TV?","en":"Do you watch TV?"}}]},"g_mashita":{"f":"V語幹 + ました / ませんでした","m":{"id":"Bentuk lampau sopan","en":"Polite past tense"},"e":{"id":"ます → ました (lampau), ません → ませんでした (lampau negatif).","en":"ます → ました (past), ません → ませんでした (past negative)."},"x":[{"jp":"昨日映画を見ました。","r":"きのうえいがをみました。","m":{"id":"Kemarin saya menonton film.","en":"I watched a movie yesterday."}},{"jp":"朝ご飯を食べませんでした。","r":"あさごはんをたべませんでした。","m":{"id":"Saya tidak sarapan.","en":"I did not eat breakfast."}},{"jp":"先週東京へ行きました。","r":"せんしゅうとうきょうへいきました。","m":{"id":"Minggu lalu saya pergi ke Tokyo.","en":"I went to Tokyo last week."}}]},"g_aru_iru":{"f":"場所 に N が あります／います","m":{"id":"あります untuk benda, います untuk orang dan hewan: 'ada'","en":"あります for things, います for people and animals: 'there is'"},"e":{"id":"Pola: tempat + に + benda + があります. Untuk makhluk hidup pakai います. Tempatnya ditandai に.","en":"Pattern: place + に + thing + があります. Use います for living beings. The place takes に."},"x":[{"jp":"机の上に本があります。","r":"つくえのうえにほんがあります。","m":{"id":"Ada buku di atas meja.","en":"There is a book on the desk."}},{"jp":"教室に先生がいます。","r":"きょうしつにせんせいがいます。","m":{"id":"Ada guru di kelas.","en":"There is a teacher in the classroom."}},{"jp":"公園に犬がいません。","r":"こうえんにいぬがいません。","m":{"id":"Tidak ada anjing di taman.","en":"There is no dog in the park."}}]},"g_adj":{"f":"い-adj: ～い／～くない／～かった　な-adj: ～な+N／～じゃない","m":{"id":"Dua jenis kata sifat: い-adj dan な-adj","en":"Two kinds of adjectives: い-adj and な-adj"},"e":{"id":"い-adj berakhir い dan berubah sendiri: たかい→たかくない (negatif)→たかかった (lampau). な-adj memakai な sebelum kata benda dan です di akhir: しずかな へや, しずかです.","en":"い-adjectives end in い and conjugate themselves: たかい→たかくない (negative)→たかかった (past). な-adjectives take な before a noun and です at the end: しずかな へや, しずかです."},"x":[{"jp":"この本は高いです。","r":"このほんはたかいです。","m":{"id":"Buku ini mahal.","en":"This book is expensive."}},{"jp":"東京は静かではありません。","r":"とうきょうはしずかではありません。","m":{"id":"Tokyo tidak sepi.","en":"Tokyo is not quiet."}},{"jp":"きれいな花ですね。","r":"きれいなはなですね。","m":{"id":"Bunganya cantik ya.","en":"What a pretty flower."}}],"n":{"id":"いい berubah menjadi よくない / よかった.","en":"いい becomes よくない / よかった."}},"g_tai":{"f":"V語幹 + たい","m":{"id":"Menyatakan keinginan sendiri: 'ingin ...'","en":"Expresses your own wish: 'want to ...'"},"e":{"id":"Ganti ます dengan たい. たい berperilaku seperti い-adj: たべたい→たべたくない. Objek boleh memakai を atau が.","en":"Replace ます with たい. It conjugates like an い-adjective: たべたい→たべたくない. The object can take を or が."},"x":[{"jp":"日本へ行きたいです。","r":"にほんへいきたいです。","m":{"id":"Saya ingin pergi ke Jepang.","en":"I want to go to Japan."}},{"jp":"水が飲みたいです。","r":"みずがのみたいです。","m":{"id":"Saya ingin minum air.","en":"I want to drink water."}},{"jp":"今日は何も食べたくないです。","r":"きょうはなにもたべたくないです。","m":{"id":"Hari ini saya tidak ingin makan apa pun.","en":"I don't want to eat anything today."}}],"n":{"id":"Untuk keinginan orang ketiga pakai ～たがっている.","en":"For a third person's wish use ～たがっている."}},"g_te_kudasai":{"f":"V-て + ください","m":{"id":"Permintaan sopan: 'tolong ...'","en":"Polite request: 'please ...'"},"e":{"id":"Ubah kata kerja ke bentuk て lalu tambahkan ください. 'Tolong jangan' memakai V-ないでください.","en":"Put the verb in て-form and add ください. Polite 'please don't': V-ないでください."},"x":[{"jp":"ここに名前を書いてください。","r":"ここになまえをかいてください。","m":{"id":"Tolong tulis nama di sini.","en":"Please write your name here."}},{"jp":"ゆっくり話してください。","r":"ゆっくりはなしてください。","m":{"id":"Tolong bicara pelan-pelan.","en":"Please speak slowly."}},{"jp":"ここで写真を撮らないでください。","r":"ここでしゃしんをとらないでください。","m":{"id":"Tolong jangan memotret di sini.","en":"Please don't take photos here."}}]},"g_te_iru":{"f":"V-て + いる","m":{"id":"Tindakan yang sedang berlangsung atau keadaan yang berlanjut","en":"An action in progress or a continuing state"},"e":{"id":"Dipakai untuk 'sedang melakukan' (たべている) dan keadaan hasil (けっこんしている 'sudah menikah', すんでいる 'tinggal').","en":"Used for 'is doing' (たべている) and resulting states (けっこんしている 'is married', すんでいる 'lives')."},"x":[{"jp":"今、ご飯を食べています。","r":"いま、ごはんをたべています。","m":{"id":"Sekarang saya sedang makan.","en":"I am eating now."}},{"jp":"私は大阪に住んでいます。","r":"わたしはおおさかにすんでいます。","m":{"id":"Saya tinggal di Osaka.","en":"I live in Osaka."}},{"jp":"兄は結婚しています。","r":"あにはけっこんしています。","m":{"id":"Kakak laki-laki saya sudah menikah.","en":"My older brother is married."}}]},"g_mashou":{"f":"V語幹 + ましょう／ませんか","m":{"id":"Ajakan dan usulan: 'ayo ...' / 'maukah ...?'","en":"Invitations and suggestions: 'let's ...' / 'won't you ...?'"},"e":{"id":"ましょう adalah ajakan langsung 'ayo'. ませんか lebih halus, seperti menawarkan 'maukah kamu ...?'.","en":"ましょう is a direct 'let's'. ませんか is softer, like 'would you like to ...?'."},"x":[{"jp":"いっしょに帰りましょう。","r":"いっしょにかえりましょう。","m":{"id":"Ayo pulang bersama.","en":"Let's go home together."}},{"jp":"お茶を飲みませんか。","r":"おちゃをのみませんか。","m":{"id":"Mau minum teh?","en":"Would you like to drink tea?"}},{"jp":"駅で会いましょう。","r":"えきであいましょう。","m":{"id":"Ayo bertemu di stasiun.","en":"Let's meet at the station."}}]},"g_nai":{"f":"V-ない形","m":{"id":"Bentuk negatif biasa (tidak sopan)","en":"Plain negative form"},"e":{"id":"Kata kerja u: ubah u terakhir jadi a + ない (かく→かかない; あう→あわない). Kata kerja ru: buang る + ない (たべる→たべない). する→しない, くる→こない.","en":"u-verbs: change the final u to a + ない (かく→かかない; あう→あわない). ru-verbs: drop る + ない (たべる→たべない). する→しない, くる→こない."},"x":[{"jp":"私は肉を食べない。","r":"わたしはにくをたべない。","m":{"id":"Saya tidak makan daging.","en":"I don't eat meat."}},{"jp":"今日は学校に行かない。","r":"きょうはがっこうにいかない。","m":{"id":"Hari ini saya tidak pergi ke sekolah.","en":"I'm not going to school today."}},{"jp":"お酒は飲まない。","r":"おさけはのまない。","m":{"id":"Saya tidak minum alkohol.","en":"I don't drink alcohol."}}]},"g_kara":{"f":"文1 + から、文2","m":{"id":"から: 'karena ...' (alasan), diletakkan setelah alasannya","en":"から: 'because ...', placed after the reason"},"e":{"id":"Alasan di depan, hasil di belakang: あめですから、いきません. から juga berarti 'dari' untuk tempat dan waktu.","en":"Reason first, result after: あめですから、いきません. から also means 'from' for places and times."},"x":[{"jp":"雨ですから、家にいます。","r":"あめですから、いえにいます。","m":{"id":"Karena hujan, saya di rumah.","en":"Because it's raining, I'll stay home."}},{"jp":"忙しいから、行けません。","r":"いそがしいから、いけません。","m":{"id":"Karena sibuk, saya tidak bisa pergi.","en":"I'm busy, so I can't go."}},{"jp":"九時から仕事です。","r":"くじからしごとです。","m":{"id":"Kerja mulai jam 9.","en":"Work starts at 9."}}]},"g_te_kara":{"f":"V-て + から","m":{"id":"Setelah melakukan A, baru B","en":"After doing A, then B"},"e":{"id":"Urutan kejadian: A dulu, lalu B. Juga dipakai untuk 'sejak ...'.","en":"Sequence: A first, then B. Also used for 'since ...'."},"x":[{"jp":"ご飯を食べてから、薬を飲みます。","r":"ごはんをたべてから、くすりをのみます。","m":{"id":"Setelah makan, saya minum obat.","en":"After eating, I take medicine."}},{"jp":"宿題をしてから、遊びます。","r":"しゅくだいをしてから、あそびます。","m":{"id":"Setelah mengerjakan PR, baru bermain.","en":"I play after doing my homework."}},{"jp":"日本に来てから、三年になります。","r":"にほんにきてから、さんねんになります。","m":{"id":"Sudah tiga tahun sejak saya datang ke Jepang.","en":"It has been three years since I came to Japan."}}]},"g_koto_ga_aru":{"f":"V-た + ことがある","m":{"id":"Pernah melakukan: pengalaman di masa lalu","en":"Have done before: past experience"},"e":{"id":"Bentuk た + ことがある = 'pernah'. Negatifnya ことがない = 'belum pernah'.","en":"た-form + ことがある = 'have done'. The negative ことがない = 'have never done'."},"x":[{"jp":"富士山に登ったことがあります。","r":"ふじさんにのぼったことがあります。","m":{"id":"Saya pernah mendaki Gunung Fuji.","en":"I have climbed Mt. Fuji."}},{"jp":"すしを食べたことがありません。","r":"すしをたべたことがありません。","m":{"id":"Saya belum pernah makan sushi.","en":"I have never eaten sushi."}},{"jp":"北海道へ行ったことがありますか。","r":"ほっかいどうへいったことがありますか。","m":{"id":"Pernahkah kamu ke Hokkaido?","en":"Have you ever been to Hokkaido?"}}]},"g_koto_ga_dekiru":{"f":"V-辞書形 + ことができる","m":{"id":"Bisa melakukan (kemampuan dan kemungkinan)","en":"Can do (ability or possibility)"},"e":{"id":"Kata kerja bentuk kamus + ことができる. Bisa untuk kemampuan maupun hal yang diizinkan keadaan. Bentuk potensial (たべられる) artinya mirip.","en":"Dictionary form + ことができる. It covers ability and what circumstances allow. The potential form (たべられる) means much the same."},"x":[{"jp":"私は日本語を話すことができます。","r":"わたしはにほんごをはなすことができます。","m":{"id":"Saya bisa berbicara bahasa Jepang.","en":"I can speak Japanese."}},{"jp":"ここでたばこを吸うことはできません。","r":"ここでたばこをすうことはできません。","m":{"id":"Di sini tidak boleh merokok.","en":"You can't smoke here."}},{"jp":"彼は泳ぐことができません。","r":"かれはおよぐことができません。","m":{"id":"Dia tidak bisa berenang.","en":"He can't swim."}}]},"g_nakereba":{"f":"V-ない → ～なければならない","m":{"id":"Harus melakukan (kewajiban)","en":"Must do (obligation)"},"e":{"id":"Buang い dari ～ない lalu tambahkan ければならない. Lisan: ～なきゃ. ～なくてはいけない mirip artinya.","en":"Drop the い of ～ない and add ければならない. Casual: ～なきゃ. ～なくてはいけない is similar."},"x":[{"jp":"毎日薬を飲まなければなりません。","r":"まいにちくすりをのまなければなりません。","m":{"id":"Saya harus minum obat setiap hari.","en":"I must take medicine every day."}},{"jp":"明日は早く起きなければならない。","r":"あしたははやくおきなければならない。","m":{"id":"Besok saya harus bangun pagi.","en":"I have to get up early tomorrow."}},{"jp":"もう帰らなきゃ。","r":"もうかえらなきゃ。","m":{"id":"Aku harus pulang sekarang.","en":"I have to go home now."}}]},"g_temo_ii":{"f":"V-て + もいい／はいけない","m":{"id":"Boleh dan tidak boleh","en":"May / must not"},"e":{"id":"V-てもいいです = boleh. Meminta izin: ～てもいいですか. Larangan: ～てはいけません.","en":"V-てもいいです = may. Asking permission: ～てもいいですか. Prohibition: ～てはいけません."},"x":[{"jp":"ここに座ってもいいですか。","r":"ここにすわってもいいですか。","m":{"id":"Bolehkah saya duduk di sini?","en":"May I sit here?"}},{"jp":"図書館で食べてはいけません。","r":"としょかんでたべてはいけません。","m":{"id":"Tidak boleh makan di perpustakaan.","en":"You must not eat in the library."}},{"jp":"この部屋は使ってもいいです。","r":"このへやはつかってもいいです。","m":{"id":"Ruangan ini boleh dipakai.","en":"You may use this room."}}]},"g_tsumori":{"f":"V-辞書形／V-ない + つもり","m":{"id":"Berniat / berencana","en":"Intend to"},"e":{"id":"Untuk niat yang sudah dipikirkan. Negatif: V-ないつもり 'berniat tidak ...'. ～つもりはない = sama sekali tidak berniat.","en":"For intentions you have thought through. Negative: V-ないつもり 'intend not to'. ～つもりはない = no intention at all."},"x":[{"jp":"来年日本へ留学するつもりです。","r":"らいねんにほんへりゅうがくするつもりです。","m":{"id":"Tahun depan saya berencana belajar ke Jepang.","en":"I plan to study in Japan next year."}},{"jp":"お酒は飲まないつもりです。","r":"おさけはのまないつもりです。","m":{"id":"Saya berniat tidak minum alkohol.","en":"I intend not to drink alcohol."}},{"jp":"彼と結婚するつもりはありません。","r":"かれとけっこんするつもりはありません。","m":{"id":"Saya sama sekali tidak berniat menikah dengannya.","en":"I have no intention of marrying him."}}]},"g_kamoshirenai":{"f":"普通形 + かもしれない","m":{"id":"Mungkin ... (kemungkinan yang tidak pasti)","en":"Might / may (uncertain possibility)"},"e":{"id":"Dipasang pada bentuk biasa. Untuk kata benda dan な-adj, だ dihilangkan: あめかもしれない. Tingkat keyakinan rendah sampai sedang.","en":"Attach to the plain form. For nouns and な-adjectives drop だ: あめかもしれない. Expresses low-to-moderate certainty."},"x":[{"jp":"明日は雨が降るかもしれません。","r":"あしたはあめがふるかもしれません。","m":{"id":"Besok mungkin hujan.","en":"It might rain tomorrow."}},{"jp":"彼は病気かもしれない。","r":"かれはびょうきかもしれない。","m":{"id":"Dia mungkin sakit.","en":"He may be sick."}},{"jp":"道が込んでいるかもしれません。","r":"みちがこんでいるかもしれません。","m":{"id":"Mungkin jalanan macet.","en":"The road might be crowded."}}]},"g_to_omou":{"f":"普通形 + と思う","m":{"id":"Menyampaikan pendapat: 'saya pikir ...'","en":"Expressing an opinion: 'I think ...'"},"e":{"id":"Bentuk biasa + と + おもう. Untuk pendapat sendiri. 'Saya kira tidak' dibuat ～ないと思う, bukan おもわない.","en":"Plain form + と + おもう, for your own opinion. 'I don't think' is ～ないと思う, not おもわない."},"x":[{"jp":"この映画はおもしろいと思います。","r":"このえいがはおもしろいとおもいます。","m":{"id":"Saya pikir film ini menarik.","en":"I think this movie is interesting."}},{"jp":"明日は雨だと思う。","r":"あしたはあめだとおもう。","m":{"id":"Kurasa besok hujan.","en":"I think it will rain tomorrow."}},{"jp":"彼は来ないと思います。","r":"かれはこないとおもいます。","m":{"id":"Saya kira dia tidak datang.","en":"I don't think he will come."}}]},"g_hou_ga_ii":{"f":"V-た／V-ない + ほうがいい","m":{"id":"Saran: 'sebaiknya ...'","en":"Advice: 'you had better ...'"},"e":{"id":"V-たほうがいい = sebaiknya lakukan. V-ないほうがいい = sebaiknya jangan. Saran yang cukup kuat.","en":"V-たほうがいい = you should do it. V-ないほうがいい = you'd better not. A fairly strong suggestion."},"x":[{"jp":"もっと野菜を食べたほうがいいです。","r":"もっとやさいをたべたほうがいいです。","m":{"id":"Sebaiknya makan lebih banyak sayur.","en":"You should eat more vegetables."}},{"jp":"夜遅くコーヒーを飲まないほうがいいですよ。","r":"よるおそくコーヒーをのまないほうがいいですよ。","m":{"id":"Sebaiknya jangan minum kopi larut malam.","en":"You'd better not drink coffee late at night."}},{"jp":"早く病院へ行ったほうがいい。","r":"はやくびょういんへいったほうがいい。","m":{"id":"Sebaiknya cepat ke rumah sakit.","en":"You'd better go to the hospital soon."}}]},"g_ageru":{"f":"V-て + あげる／くれる／もらう","m":{"id":"Memberi dan menerima kebaikan","en":"Giving and receiving favours"},"e":{"id":"あげる: saya melakukan untuk orang lain. くれる: orang lain melakukan untuk saya. もらう: saya menerima, pelakunya ditandai に.","en":"あげる: I do it for someone. くれる: someone does it for me. もらう: I receive it; the doer is marked with に."},"x":[{"jp":"友だちに本を貸してあげました。","r":"ともだちにほんをかしてあげました。","m":{"id":"Saya meminjamkan buku kepada teman.","en":"I lent a book to my friend."}},{"jp":"母がケーキを作ってくれました。","r":"ははがケーキをつくってくれました。","m":{"id":"Ibu membuatkan kue untuk saya.","en":"My mother made a cake for me."}},{"jp":"先生に日本語を教えてもらいました。","r":"せんせいににほんごをおしえてもらいました。","m":{"id":"Saya diajari bahasa Jepang oleh guru.","en":"I had my teacher teach me Japanese."}}]},"g_passive":{"f":"V-(ら)れる","m":{"id":"Bentuk pasif: dikenai tindakan","en":"Passive: being acted upon"},"e":{"id":"Kata kerja u: u→a + れる (かく→かかれる). Kata kerja ru: る→られる. する→される, くる→こられる. Pelaku ditandai に. Bisa juga bermakna 'dirugikan'.","en":"u-verbs: u→a + れる (かく→かかれる). ru-verbs: る→られる. する→される, くる→こられる. The agent takes に. It can also express being adversely affected."},"x":[{"jp":"私は先生にほめられました。","r":"わたしはせんせいにほめられました。","m":{"id":"Saya dipuji oleh guru.","en":"I was praised by my teacher."}},{"jp":"この本は多くの人に読まれています。","r":"このほんはおおくのひとによまれています。","m":{"id":"Buku ini dibaca banyak orang.","en":"This book is read by many people."}},{"jp":"雨に降られて、びしょぬれになった。","r":"あめにふられて、びしょぬれになった。","m":{"id":"Kehujanan, saya basah kuyup.","en":"I got caught in the rain and was soaked."}}]},"g_causative":{"f":"V-(さ)せる","m":{"id":"Kausatif: menyuruh atau membiarkan orang melakukan","en":"Causative: make or let someone do"},"e":{"id":"Kata kerja u: u→a + せる (のむ→のませる). Kata kerja ru: る→させる. する→させる, くる→こさせる. Orang yang disuruh ditandai に (atau を bila kata kerjanya tanpa objek).","en":"u-verbs: u→a + せる (のむ→のませる). ru-verbs: る→させる. する→させる, くる→こさせる. The person made to act takes に (or を if the verb has no object)."},"x":[{"jp":"母は子どもに野菜を食べさせます。","r":"はははこどもにやさいをたべさせます。","m":{"id":"Ibu menyuruh anaknya makan sayur.","en":"Mother makes her child eat vegetables."}},{"jp":"先生は学生を帰らせました。","r":"せんせいはがくせいをかえらせました。","m":{"id":"Guru mengizinkan siswa pulang.","en":"The teacher let the students go home."}},{"jp":"私に説明させてください。","r":"わたしにせつめいさせてください。","m":{"id":"Tolong biarkan saya menjelaskan.","en":"Please let me explain."}}]},"g_tara":{"f":"V-た + ら","m":{"id":"Kalau/jika ... (bersyarat), atau 'setelah ...'","en":"If / when ... (conditional)"},"e":{"id":"Bentuk た + ら. Untuk syarat, dan untuk 'ketika/setelah' sesuatu terjadi. Boleh diikuti saran, permintaan, atau niat.","en":"た-form + ら. Used for conditions and for 'when/after' something happens. Can be followed by suggestions, requests or intentions."},"x":[{"jp":"時間があったら、手伝ってください。","r":"じかんがあったら、てつだってください。","m":{"id":"Kalau ada waktu, tolong bantu.","en":"If you have time, please help."}},{"jp":"日本に着いたら、電話します。","r":"にほんについたら、でんわします。","m":{"id":"Setelah sampai di Jepang, saya akan menelepon.","en":"I'll call you when I arrive in Japan."}},{"jp":"安かったら、買います。","r":"やすかったら、かいます。","m":{"id":"Kalau murah, saya beli.","en":"If it's cheap, I'll buy it."}}]},"g_ba":{"f":"V-ば（条件形）","m":{"id":"Syarat: 'kalau ... (maka wajarnya ...)'","en":"Conditional: 'if ... (then naturally ...)'"},"e":{"id":"Kata kerja u: u→e + ば (かく→かけば). Kata kerja ru: る→れば. い-adj: い→ければ. Cocok untuk hasil yang wajar; kurang cocok bila diikuti perintah atau permintaan.","en":"u-verbs: u→e + ば (かく→かけば). ru-verbs: る→れば. い-adj: い→ければ. Best for natural results; less suited to commands or requests afterwards."},"x":[{"jp":"春になれば、花が咲きます。","r":"はるになれば、はながさきます。","m":{"id":"Kalau musim semi tiba, bunga mekar.","en":"When spring comes, flowers bloom."}},{"jp":"急げば、間に合います。","r":"いそげば、まにあいます。","m":{"id":"Kalau bergegas, akan sempat.","en":"If you hurry, you'll make it."}},{"jp":"安ければ、買いたいです。","r":"やすければ、かいたいです。","m":{"id":"Kalau murah, saya ingin membelinya.","en":"If it's cheap, I'd like to buy it."}}]},"g_nagara":{"f":"V語幹 + ながら","m":{"id":"Melakukan dua hal sekaligus","en":"Doing two things at once"},"e":{"id":"Dua tindakan bersamaan oleh orang yang sama. Tindakan utama ada di akhir kalimat.","en":"Two simultaneous actions by the same person. The main action comes at the end."},"x":[{"jp":"音楽を聞きながら、勉強します。","r":"おんがくをききながら、べんきょうします。","m":{"id":"Saya belajar sambil mendengarkan musik.","en":"I study while listening to music."}},{"jp":"歩きながら話しましょう。","r":"あるきながらはなしましょう。","m":{"id":"Ayo bicara sambil berjalan.","en":"Let's talk while walking."}},{"jp":"テレビを見ながらご飯を食べる。","r":"テレビをみながらごはんをたべる。","m":{"id":"Makan sambil menonton TV.","en":"I eat while watching TV."}}]},"g_sugiru":{"f":"V語幹／い-adj語幹／な-adj + すぎる","m":{"id":"Terlalu ... (berlebihan)","en":"Too much / excessive"},"e":{"id":"Tambahkan すぎる pada akar kata kerja, い-adj (buang い), atau な-adj. Biasanya bernada negatif.","en":"Add すぎる to a verb stem, an い-adjective (drop い) or a な-adjective. Usually carries a negative nuance."},"x":[{"jp":"昨日は食べすぎました。","r":"きのうはたべすぎました。","m":{"id":"Kemarin saya terlalu banyak makan.","en":"I ate too much yesterday."}},{"jp":"この部屋は暑すぎます。","r":"このへやはあつすぎます。","m":{"id":"Ruangan ini terlalu panas.","en":"This room is too hot."}},{"jp":"この問題は難しすぎる。","r":"このもんだいはむずかしすぎる。","m":{"id":"Soal ini terlalu sulit.","en":"This problem is too difficult."}}]},"g_you_ni_suru":{"f":"V-辞書形／V-ない + ようにする／なる","m":{"id":"Berusaha untuk ... / menjadi bisa ...","en":"Make an effort to ... / come to ..."},"e":{"id":"ようにする: berusaha membiasakan atau menjaga sesuatu. ようになる: perubahan keadaan, jadi bisa atau jadi begitu. Biasanya dengan bentuk kamus atau potensial.","en":"ようにする: make an effort to do or keep doing something. ようになる: a change of state, coming to be able to or to do. Usually with the dictionary or potential form."},"x":[{"jp":"毎日運動するようにしています。","r":"まいにちうんどうするようにしています。","m":{"id":"Saya berusaha berolahraga tiap hari.","en":"I try to exercise every day."}},{"jp":"日本語が話せるようになりました。","r":"にほんごがはなせるようになりました。","m":{"id":"Saya jadi bisa berbicara bahasa Jepang.","en":"I've become able to speak Japanese."}},{"jp":"遅れないようにしてください。","r":"おくれないようにしてください。","m":{"id":"Usahakan jangan terlambat.","en":"Please try not to be late."}}]},"g_koto_ni_suru":{"f":"V-辞書形／V-ない + ことにする／ことになる","m":{"id":"Memutuskan sendiri / telah diputuskan (oleh pihak lain atau keadaan)","en":"Decide to / it has been decided that"},"e":{"id":"ことにする = keputusan pribadi. ことになる = hasil keputusan (organisasi atau keadaan), sering untuk pengumuman dan aturan.","en":"ことにする = a personal decision. ことになる = a decision made by others or by circumstances, often for announcements and rules."},"x":[{"jp":"来月から禁煙することにしました。","r":"らいげつからきんえんすることにしました。","m":{"id":"Saya memutuskan berhenti merokok mulai bulan depan.","en":"I decided to quit smoking from next month."}},{"jp":"来年、大阪に転勤することになりました。","r":"らいねん、おおさかにてんきんすることになりました。","m":{"id":"Tahun depan saya akan dipindahtugaskan ke Osaka.","en":"It's been decided I'll be transferred to Osaka next year."}},{"jp":"夜は十時に寝ることにしている。","r":"よるはじゅうじにねることにしている。","m":{"id":"Saya membuat aturan tidur jam 10 malam.","en":"I make it a rule to go to bed at 10 pm."}}]},"g_hazu":{"f":"普通形 + はず","m":{"id":"Seharusnya / pasti ... (dugaan berdasar alasan)","en":"Should be / expected to (based on grounds)"},"e":{"id":"Dugaan yang berdasar. N の / な-adj な + はず. Negatif: はずがない 'tidak mungkin'; はずだった 'seharusnya (tapi ternyata tidak)'.","en":"A grounded expectation. N の / な-adj な + はず. はずがない = 'there's no way'; はずだった = 'was supposed to (but didn't)'."},"x":[{"jp":"彼はもう家に着いたはずです。","r":"かれはもういえについたはずです。","m":{"id":"Seharusnya dia sudah sampai rumah.","en":"He should have arrived home by now."}},{"jp":"この店は安いはずだ。","r":"このみせはやすいはずだ。","m":{"id":"Toko ini seharusnya murah.","en":"This shop should be cheap."}},{"jp":"彼が知っているはずがありません。","r":"かれがしっているはずがありません。","m":{"id":"Tidak mungkin dia tahu.","en":"There's no way he knows."}}]},"g_rashii_youda":{"f":"普通形 + らしい／ようだ／みたいだ","m":{"id":"Katanya / sepertinya (kabar atau kesan)","en":"Apparently / seems (hearsay and appearance)"},"e":{"id":"らしい: berdasar kabar atau bukti tidak langsung. ようだ／みたいだ: kesan dari pengamatan sendiri (みたいだ lebih santai).","en":"らしい: based on hearsay or indirect evidence. ようだ／みたいだ: an impression from your own observation (みたいだ is more casual)."},"x":[{"jp":"田中さんは来週結婚するらしい。","r":"たなかさんはらいしゅうけっこんするらしい。","m":{"id":"Katanya Tanaka akan menikah minggu depan.","en":"I hear Tanaka is getting married next week."}},{"jp":"彼は疲れているようです。","r":"かれはつかれているようです。","m":{"id":"Dia sepertinya lelah.","en":"He seems tired."}},{"jp":"外は寒いみたいだよ。","r":"そとはさむいみたいだよ。","m":{"id":"Di luar sepertinya dingin.","en":"It seems cold outside."}}]},"g_wake":{"f":"普通形 + わけだ／わけではない","m":{"id":"'Pantas saja / jadi memang ...' dan 'bukan berarti ...'","en":"'No wonder / that explains it' and 'it doesn't mean that ...'"},"e":{"id":"～わけだ: kesimpulan logis, 'pantas'. ～わけではない: menyangkal sebagian, 'bukan berarti'.","en":"～わけだ: a logical conclusion, 'no wonder'. ～わけではない: a partial denial, 'it's not that ...'."},"x":[{"jp":"毎日練習したから、上手なわけだ。","r":"まいにちれんしゅうしたから、じょうずなわけだ。","m":{"id":"Karena latihan tiap hari, pantas saja pandai.","en":"He practiced every day, so no wonder he's good."}},{"jp":"嫌いなわけではありません。","r":"きらいなわけではありません。","m":{"id":"Bukan berarti saya benci.","en":"It's not that I dislike it."}},{"jp":"お金がないわけではないが、買わない。","r":"おかねがないわけではないが、かわない。","m":{"id":"Bukan berarti tidak punya uang, tapi saya tidak membeli.","en":"It's not that I have no money, but I won't buy it."}}]},"g_te_shimau":{"f":"V-て + しまう","m":{"id":"Terlanjur / tuntas ... (penyesalan atau selesai)","en":"Complete the action / regrettably did"},"e":{"id":"Menyatakan tindakan yang tuntas, atau yang disesalkan. Lisan: ～ちゃう／～じゃう.","en":"Expresses a completed action or one that is regretted. Casual: ～ちゃう／～じゃう."},"x":[{"jp":"宿題を全部やってしまいました。","r":"しゅくだいをぜんぶやってしまいました。","m":{"id":"PR-nya sudah saya selesaikan semua.","en":"I finished all my homework."}},{"jp":"電車に傘を忘れてしまいました。","r":"でんしゃにかさをわすれてしまいました。","m":{"id":"Payung saya tertinggal di kereta.","en":"I left my umbrella on the train."}},{"jp":"財布を落としちゃった。","r":"さいふをおとしちゃった。","m":{"id":"Dompetku terjatuh, aduh.","en":"Oops, I dropped my wallet."}}]},"g_te_oku_miru":{"f":"V-て + おく／みる","m":{"id":"Menyiapkan lebih dulu / mencoba melakukan","en":"Do in advance / try doing"},"e":{"id":"～ておく: dilakukan sebagai persiapan. ～てみる: mencoba untuk melihat hasilnya.","en":"～ておく: done as preparation. ～てみる: try it and see."},"x":[{"jp":"旅行の前にホテルを予約しておきます。","r":"りょこうのまえにホテルをよやくしておきます。","m":{"id":"Sebelum liburan, saya memesan hotel dulu.","en":"I book a hotel before the trip."}},{"jp":"この料理を食べてみてください。","r":"このりょうりをたべてみてください。","m":{"id":"Cobalah makan masakan ini.","en":"Please try this dish."}},{"jp":"窓を開けておいてください。","r":"まどをあけておいてください。","m":{"id":"Tolong biarkan jendela terbuka.","en":"Please leave the window open."}}]},"g_ni_tsuite":{"f":"N + について／によって","m":{"id":"Tentang ... / tergantung ... atau oleh ...","en":"About ... / depending on ... or by ..."},"e":{"id":"～について = 'tentang' suatu topik. ～によって = 'tergantung' (hasil berbeda-beda), 'oleh' (pelaku pada kalimat pasif), atau 'dengan cara'.","en":"～について = 'about' a topic. ～によって = 'depending on' (results vary), 'by' (agent in the passive), or 'by means of'."},"x":[{"jp":"日本の文化について調べています。","r":"にほんのぶんかについてしらべています。","m":{"id":"Saya sedang meneliti budaya Jepang.","en":"I'm researching Japanese culture."}},{"jp":"人によって考え方が違います。","r":"ひとによってかんがえかたがちがいます。","m":{"id":"Cara berpikir berbeda tergantung orangnya.","en":"Ways of thinking differ from person to person."}},{"jp":"この絵はピカソによって描かれた。","r":"このえはピカソによってかかれた。","m":{"id":"Lukisan ini dilukis oleh Picasso.","en":"This picture was painted by Picasso."}}]},"g_noni":{"f":"普通形 + のに","m":{"id":"Padahal / meskipun ...","en":"Although / even though"},"e":{"id":"Hasil yang tidak sesuai harapan, sering bernada kecewa. な-adj dan benda memakai なのに.","en":"A result contrary to expectation, often with disappointment. な-adjectives and nouns take なのに."},"x":[{"jp":"勉強したのに、試験に落ちました。","r":"べんきょうしたのに、しけんにおちました。","m":{"id":"Padahal sudah belajar, saya gagal ujian.","en":"Even though I studied, I failed the exam."}},{"jp":"春なのに、まだ寒いです。","r":"はるなのに、まださむいです。","m":{"id":"Padahal musim semi, masih dingin.","en":"It's spring, yet it's still cold."}},{"jp":"約束したのに、彼は来なかった。","r":"やくそくしたのに、かれはこなかった。","m":{"id":"Padahal sudah janji, dia tidak datang.","en":"He promised, yet he didn't come."}}]},"g_baai":{"f":"普通形／N の + 場合（は）","m":{"id":"Dalam hal / jika terjadi ...","en":"In the case that ..."},"e":{"id":"Untuk situasi tertentu yang mungkin terjadi, sering dengan instruksi atau aturan. Kata benda: Nの場合.","en":"For a particular situation that may occur, often with instructions or rules. Nouns: Nの場合."},"x":[{"jp":"火事の場合は、非常口を使ってください。","r":"かじのばあいは、ひじょうぐちをつかってください。","m":{"id":"Jika terjadi kebakaran, gunakan pintu darurat.","en":"In case of fire, use the emergency exit."}},{"jp":"雨の場合は、中止です。","r":"あめのばあいは、ちゅうしです。","m":{"id":"Jika hujan, acara dibatalkan.","en":"If it rains, it will be cancelled."}},{"jp":"遅れる場合は、連絡してください。","r":"おくれるばあいは、れんらくしてください。","m":{"id":"Jika akan terlambat, tolong hubungi.","en":"If you will be late, please contact us."}}]},"g_mama":{"f":"V-た／V-ない／N の + まま","m":{"id":"Tetap dalam keadaan ... (tanpa berubah)","en":"Remaining as is"},"e":{"id":"Keadaan tidak berubah padahal seharusnya berubah. ～たまま = tetap dalam keadaan setelah melakukan sesuatu.","en":"A state stays unchanged when you would expect it to change. ～たまま = remaining in the state after doing something."},"x":[{"jp":"窓を開けたまま、寝てしまった。","r":"まどをあけたまま、ねてしまった。","m":{"id":"Saya tertidur dengan jendela tetap terbuka.","en":"I fell asleep with the window left open."}},{"jp":"靴を履いたまま、部屋に入らないでください。","r":"くつをはいたまま、へやにはいらないでください。","m":{"id":"Jangan masuk kamar dengan sepatu terpasang.","en":"Please don't enter the room with your shoes on."}},{"jp":"昔のままの町です。","r":"むかしのままのまちです。","m":{"id":"Kota ini masih sama seperti dulu.","en":"It's a town just as it used to be."}}]},"g_tokoro":{"f":"V + ところだ","m":{"id":"Tepat akan / sedang / baru saja melakukan","en":"About to / in the middle of / just did"},"e":{"id":"Bentuk kamus + ところ = akan; ている + ところ = sedang; た + ところ = baru saja.","en":"Dictionary form + ところ = about to; ている + ところ = in the middle of; た + ところ = just did."},"x":[{"jp":"今から出かけるところです。","r":"いまからでかけるところです。","m":{"id":"Saya baru mau berangkat.","en":"I'm just about to head out."}},{"jp":"今、ご飯を食べているところです。","r":"いま、ごはんをたべているところです。","m":{"id":"Sekarang saya sedang makan.","en":"I'm in the middle of eating now."}},{"jp":"さっき家に着いたところです。","r":"さっきいえについたところです。","m":{"id":"Saya baru saja sampai rumah.","en":"I just got home."}}]},"g_bakari":{"f":"V-た／N + ばかり","m":{"id":"Hanya / melulu / baru saja","en":"Only / nothing but / just (done)"},"e":{"id":"N + ばかり = hanya N saja (berlebihan). V-たばかり = baru saja melakukan, terasa lebih dekat dari ところ.","en":"N + ばかり = nothing but N (to excess). V-たばかり = just did, feeling closer in time than ところ."},"x":[{"jp":"彼はゲームばかりしています。","r":"かれはゲームばかりしています。","m":{"id":"Dia main game melulu.","en":"He does nothing but play games."}},{"jp":"日本に来たばかりです。","r":"にほんにきたばかりです。","m":{"id":"Saya baru saja datang ke Jepang.","en":"I just came to Japan."}},{"jp":"お菓子ばかり食べてはいけません。","r":"おかしばかりたべてはいけません。","m":{"id":"Jangan makan camilan melulu.","en":"You shouldn't eat only sweets."}}]},"g_naide":{"f":"V-ない + で／ず(に)","m":{"id":"Tanpa melakukan ...","en":"Without doing"},"e":{"id":"V-ないで = melakukan B tanpa A. ずに lebih bergaya tulis; する → せずに.","en":"V-ないで = do B without doing A. ずに is more written style; する → せずに."},"x":[{"jp":"朝ご飯を食べないで、学校へ行きました。","r":"あさごはんをたべないで、がっこうへいきました。","m":{"id":"Saya ke sekolah tanpa sarapan.","en":"I went to school without eating breakfast."}},{"jp":"辞書を使わずに、この本を読みました。","r":"じしょをつかわずに、このほんをよみました。","m":{"id":"Saya membaca buku ini tanpa kamus.","en":"I read this book without a dictionary."}},{"jp":"何も言わないで、帰ってしまった。","r":"なにもいわないで、かえってしまった。","m":{"id":"Dia pulang tanpa berkata apa pun.","en":"He went home without saying anything."}}]},"g_toori":{"f":"V-辞書形／V-た／N の + とおり(に)","m":{"id":"Persis seperti ...","en":"Exactly as ..."},"e":{"id":"Melakukan sesuai dengan sesuatu. Kata benda: Nのとおりに.","en":"Doing something in accordance with something. Nouns: Nのとおりに."},"x":[{"jp":"私が言うとおりにしてください。","r":"わたしがいうとおりにしてください。","m":{"id":"Lakukan persis seperti yang saya katakan.","en":"Please do exactly as I say."}},{"jp":"説明書のとおりに組み立てました。","r":"せつめいしょのとおりにくみたてました。","m":{"id":"Saya merakitnya sesuai buku petunjuk.","en":"I assembled it as per the manual."}},{"jp":"思ったとおり、おいしかった。","r":"おもったとおり、おいしかった。","m":{"id":"Seperti dugaan, enak.","en":"As I expected, it was delicious."}}]},"g_ni_chigainai":{"f":"普通形 + に違いない","m":{"id":"Pasti ... (yakin berdasar alasan)","en":"Must be ... (strong conviction)"},"e":{"id":"Lebih kuat dari かもしれない: pembicara hampir pasti. Kata benda dan な-adj tanpa だ.","en":"Stronger than かもしれない: the speaker is nearly certain. Nouns and な-adjectives drop だ."},"x":[{"jp":"あの人が犯人に違いない。","r":"あのひとがはんにんにちがいない。","m":{"id":"Orang itu pasti pelakunya.","en":"That person must be the culprit."}},{"jp":"この問題は彼には難しいに違いない。","r":"このもんだいはかれにはむずかしいにちがいない。","m":{"id":"Soal ini pasti sulit baginya.","en":"This problem must be difficult for him."}},{"jp":"電気がついているから、まだ起きているに違いない。","r":"でんきがついているから、まだおきているにちがいない。","m":{"id":"Lampunya menyala, jadi dia pasti masih bangun.","en":"The light is on, so he must still be awake."}}]},"g_wake_niwa":{"f":"V-辞書形／V-ない + わけにはいかない","m":{"id":"Tidak bisa (karena alasan moral atau keadaan)","en":"Cannot (because of circumstances)"},"e":{"id":"Bukan tidak mampu, tapi tidak pantas atau tidak bisa dilakukan karena keadaan. ～ないわけにはいかない = tidak bisa tidak melakukan.","en":"Not about ability but about circumstances or duty that rule it out. ～ないわけにはいかない = cannot not do."},"x":[{"jp":"明日は試験だから、遊ぶわけにはいかない。","r":"あしたはしけんだから、あそぶわけにはいかない。","m":{"id":"Besok ujian, jadi tidak bisa bermain-main.","en":"I have an exam tomorrow, so I can't afford to play."}},{"jp":"上司の命令だから、断るわけにはいきません。","r":"じょうしのめいれいだから、ことわるわけにはいきません。","m":{"id":"Karena perintah atasan, saya tidak bisa menolak.","en":"It's my boss's order, so I can't refuse."}},{"jp":"約束した以上、行かないわけにはいかない。","r":"やくそくしたいじょう、いかないわけにはいかない。","m":{"id":"Karena sudah berjanji, saya tidak bisa tidak pergi.","en":"Having promised, I can't not go."}}]},"g_monono":{"f":"普通形 + ものの","m":{"id":"Memang ..., tetapi ...","en":"Although ..., (but)"},"e":{"id":"Gaya tulis. Mengakui kenyataan pertama, tetapi hasilnya tidak sesuai.","en":"Written style. Acknowledges the first fact, but the outcome doesn't match."},"x":[{"jp":"新しい車を買ったものの、ほとんど乗っていない。","r":"あたらしいくるまをかったものの、ほとんどのっていない。","m":{"id":"Memang sudah beli mobil baru, tapi hampir tidak dipakai.","en":"I bought a new car, but I hardly drive it."}},{"jp":"ダイエットを始めたものの、続かなかった。","r":"ダイエットをはじめたものの、つづかなかった。","m":{"id":"Memang sudah mulai diet, tapi tidak bertahan.","en":"I started a diet, but couldn't keep it up."}},{"jp":"頭ではわかっているものの、行動に移せない。","r":"あたまではわかっているものの、こうどうにうつせない。","m":{"id":"Di kepala paham, tapi tidak bisa bertindak.","en":"I understand in my head, but can't act on it."}}]},"g_nimokakawarazu":{"f":"N／普通形 + にもかかわらず","m":{"id":"Walaupun ... tetap ...","en":"Despite / in spite of"},"e":{"id":"Lebih formal dari のに. Bagian belakangnya tidak boleh berupa perintah atau ajakan.","en":"More formal than のに. The second half cannot be a command or invitation."},"x":[{"jp":"雨にもかかわらず、大勢の人が集まった。","r":"あめにもかかわらず、おおぜいのひとがあつまった。","m":{"id":"Walaupun hujan, banyak orang berkumpul.","en":"Despite the rain, many people gathered."}},{"jp":"忙しいにもかかわらず、手伝ってくれた。","r":"いそがしいにもかかわらず、てつだってくれた。","m":{"id":"Walaupun sibuk, dia membantu saya.","en":"Despite being busy, he helped me."}},{"jp":"努力したにもかかわらず、結果は出なかった。","r":"どりょくしたにもかかわらず、けっかはでなかった。","m":{"id":"Walaupun sudah berusaha, hasilnya tidak muncul.","en":"Despite my effort, no results came."}}]},"g_wo_hajime":{"f":"N + をはじめ（として）","m":{"id":"Mulai dari ... (dan lainnya)","en":"Starting with / including ... and others"},"e":{"id":"Menyebut contoh utama lalu menyiratkan banyak yang lain.","en":"Names a main example and implies many others."},"x":[{"jp":"社長をはじめ、社員全員が参加した。","r":"しゃちょうをはじめ、しゃいんぜんいんがさんかした。","m":{"id":"Mulai dari direktur, seluruh karyawan ikut serta.","en":"Starting with the president, all employees took part."}},{"jp":"東京をはじめとして、多くの都市で雪が降った。","r":"とうきょうをはじめとして、おおくのとしでゆきがふった。","m":{"id":"Salju turun di banyak kota termasuk Tokyo.","en":"It snowed in many cities, including Tokyo."}},{"jp":"家族をはじめ、友人にも感謝しています。","r":"かぞくをはじめ、ゆうじんにもかんしゃしています。","m":{"id":"Saya berterima kasih kepada keluarga dan juga teman-teman.","en":"I'm grateful to everyone, starting with my family and friends."}}]},"g_ni_taishite":{"f":"N + に対して","m":{"id":"Terhadap ... / berbeda dengan ...","en":"Towards / in contrast to"},"e":{"id":"Objek sikap atau tindakan: Nに対して. Juga untuk kontras: ～に対して、～は ...","en":"Marks the target of an attitude or action: Nに対して. Also contrast: ～に対して、～は ..."},"x":[{"jp":"お客様に対して、失礼なことを言ってはいけません。","r":"おきゃくさまにたいして、しつれいなことをいってはいけません。","m":{"id":"Jangan mengatakan hal tidak sopan kepada pelanggan.","en":"You must not say rude things to customers."}},{"jp":"兄は社交的なのに対して、弟は内気だ。","r":"あにはしゃこうてきなのにたいして、おとうとはうちきだ。","m":{"id":"Kakak ramah, sedangkan adik pemalu.","en":"My older brother is sociable, whereas my younger brother is shy."}},{"jp":"この質問に対して、答えてください。","r":"このしつもんにたいして、こたえてください。","m":{"id":"Tolong jawab pertanyaan ini.","en":"Please respond to this question."}}]},"g_ni_kanshite":{"f":"N + に関して","m":{"id":"Mengenai ...","en":"Regarding / concerning"},"e":{"id":"Gaya formal, mirip ～について tapi lebih resmi. Bentuk penjelas kata benda: ～に関する+N.","en":"Formal, similar to ～について but more official. Noun-modifying form: ～に関する+N."},"x":[{"jp":"この件に関して、ご質問はありますか。","r":"このけんにかんして、ごしつもんはありますか。","m":{"id":"Adakah pertanyaan mengenai hal ini?","en":"Do you have any questions about this matter?"}},{"jp":"環境問題に関して、意見を述べた。","r":"かんきょうもんだいにかんして、いけんをのべた。","m":{"id":"Saya menyampaikan pendapat mengenai masalah lingkungan.","en":"I gave my opinion on environmental problems."}},{"jp":"日本の歴史に関する本を読んでいる。","r":"にほんのれきしにかんするほんをよんでいる。","m":{"id":"Saya membaca buku tentang sejarah Jepang.","en":"I'm reading a book on Japanese history."}}]},"g_okage_sei":{"f":"普通形 + おかげで／せいで","m":{"id":"Berkat ... / gara-gara ...","en":"Thanks to / because of (negative)"},"e":{"id":"おかげで = penyebab yang baik. せいで = penyebab yang buruk, bernada menyalahkan.","en":"おかげで = a good cause. せいで = a bad cause, with a tone of blame."},"x":[{"jp":"先生のおかげで、合格できました。","r":"せんせいのおかげで、ごうかくできました。","m":{"id":"Berkat guru, saya bisa lulus.","en":"Thanks to my teacher, I passed."}},{"jp":"寝坊したせいで、電車に乗り遅れた。","r":"ねぼうしたせいで、でんしゃにのりおくれた。","m":{"id":"Gara-gara kesiangan, saya ketinggalan kereta.","en":"Because I overslept, I missed the train."}},{"jp":"天気が悪かったせいで、旅行が中止になった。","r":"てんきがわるかったせいで、りょこうがちゅうしになった。","m":{"id":"Gara-gara cuaca buruk, perjalanan dibatalkan.","en":"The trip was cancelled because of the bad weather."}}]},"g_bakari_denaku":{"f":"N／普通形 + ばかりでなく","m":{"id":"Bukan hanya ..., tetapi juga ...","en":"Not only ... but also"},"e":{"id":"Biasanya diikuti も atau まで. Setara dengan ～だけでなく.","en":"Usually followed by も or まで. Equivalent to ～だけでなく."},"x":[{"jp":"彼は英語ばかりでなく、中国語も話せる。","r":"かれはえいごばかりでなく、ちゅうごくごもはなせる。","m":{"id":"Dia bukan hanya bisa bahasa Inggris, tapi juga Mandarin.","en":"He can speak not only English but also Chinese."}},{"jp":"この店は安いばかりでなく、味もいい。","r":"このみせはやすいばかりでなく、あじもいい。","m":{"id":"Toko ini bukan hanya murah, rasanya juga enak.","en":"This shop is not only cheap but also tasty."}},{"jp":"子どもばかりでなく、大人も楽しめる。","r":"こどもばかりでなく、おとなもたのしめる。","m":{"id":"Bukan hanya anak-anak, orang dewasa juga bisa menikmatinya.","en":"Not just children, adults can enjoy it too."}}]},"g_towa_kagiranai":{"f":"普通形 + とは限らない","m":{"id":"Belum tentu ...","en":"Not necessarily"},"e":{"id":"Menyangkal generalisasi: 'tidak selalu'. Sering bersama いつも, 必ず.","en":"Denies a generalization: 'not always'. Often used with いつも or 必ず."},"x":[{"jp":"高い物がいい物とは限らない。","r":"たかいものがいいものとはかぎらない。","m":{"id":"Barang mahal belum tentu bagus.","en":"Expensive things aren't necessarily good."}},{"jp":"お金持ちが幸せだとは限りません。","r":"おかねもちがしあわせだとはかぎりません。","m":{"id":"Orang kaya belum tentu bahagia.","en":"Rich people aren't necessarily happy."}},{"jp":"有名な店がおいしいとは限らない。","r":"ゆうめいなみせがおいしいとはかぎらない。","m":{"id":"Toko terkenal belum tentu enak.","en":"Famous restaurants aren't necessarily delicious."}}]},"g_zaru_wo_enai":{"f":"V-ない(語幹) + ざるを得ない","m":{"id":"Terpaksa harus ... (tidak ada pilihan)","en":"Have no choice but to"},"e":{"id":"Gaya tulis atau formal. する → せざるを得ない.","en":"Written or formal style. する → せざるを得ない."},"x":[{"jp":"台風で、旅行をあきらめざるを得なかった。","r":"たいふうで、りょこうをあきらめざるをえなかった。","m":{"id":"Karena topan, terpaksa membatalkan perjalanan.","en":"Because of the typhoon, we had no choice but to give up the trip."}},{"jp":"会社の方針だから、従わざるを得ません。","r":"かいしゃのほうしんだから、したがわざるをえません。","m":{"id":"Karena kebijakan perusahaan, saya terpaksa menurut.","en":"It's company policy, so I have no choice but to comply."}},{"jp":"彼の意見は認めざるを得ない。","r":"かれのいけんはみとめざるをえない。","m":{"id":"Saya harus mengakui pendapatnya.","en":"I have to admit his opinion is right."}}]},"g_kaneru":{"f":"V語幹 + かねる／かねない","m":{"id":"Sulit/tidak bisa ... / bisa-bisa ...","en":"Cannot bring oneself to / might well"},"e":{"id":"かねる = tidak bisa (cara sopan menolak). かねない = bisa saja terjadi hal buruk.","en":"かねる = cannot (a polite way to refuse). かねない = something bad could well happen."},"x":[{"jp":"その件は、私ではお答えしかねます。","r":"そのけんは、わたしではおこたえしかねます。","m":{"id":"Mengenai hal itu, saya tidak dapat menjawab.","en":"I'm afraid I can't answer that."}},{"jp":"そんな運転では、事故を起こしかねない。","r":"そんなうんてんでは、じこをおこしかねない。","m":{"id":"Mengemudi begitu bisa-bisa menyebabkan kecelakaan.","en":"Driving like that could well cause an accident."}},{"jp":"賛成しかねます。","r":"さんせいしかねます。","m":{"id":"Saya sulit menyetujui.","en":"I find it hard to agree."}}]},"g_tsutsu":{"f":"V語幹 + つつ(ある)","m":{"id":"Sambil ... / sedang berangsur ...","en":"While doing / gradually in the process of"},"e":{"id":"つつ = sambil (gaya tulis). つつある = sedang berangsur berubah, perubahan yang terus berlanjut.","en":"つつ = while (written style). つつある = gradually changing, a change in progress."},"x":[{"jp":"景気は回復しつつあります。","r":"けいきはかいふくしつつあります。","m":{"id":"Ekonomi sedang berangsur pulih.","en":"The economy is gradually recovering."}},{"jp":"悪いと知りつつ、また食べてしまった。","r":"わるいとしりつつ、またたべてしまった。","m":{"id":"Meski tahu itu buruk, saya makan lagi.","en":"Knowing it was bad, I ate it again."}},{"jp":"人口が減りつつある。","r":"じんこうがへりつつある。","m":{"id":"Jumlah penduduk sedang berkurang.","en":"The population is decreasing."}}]},"g_wo_kikkake":{"f":"N／V-た + をきっかけに","m":{"id":"Bermula dari ... / dipicu oleh ...","en":"Triggered by / on the occasion of"},"e":{"id":"Pemicu atau momen mulainya suatu perubahan.","en":"The trigger or occasion that starts a change."},"x":[{"jp":"病気をきっかけに、健康に気をつけるようになった。","r":"びょうきをきっかけに、けんこうにきをつけるようになった。","m":{"id":"Sejak sakit, saya mulai menjaga kesehatan.","en":"After my illness, I started taking care of my health."}},{"jp":"留学をきっかけに、英語が好きになった。","r":"りゅうがくをきっかけに、えいごがすきになった。","m":{"id":"Berawal dari belajar di luar negeri, saya jadi suka bahasa Inggris.","en":"Studying abroad made me like English."}},{"jp":"引っ越したのをきっかけに、犬を飼い始めた。","r":"ひっこしたのをきっかけに、いぬをかいはじめた。","m":{"id":"Setelah pindah rumah, saya mulai memelihara anjing.","en":"I got a dog when I moved."}}]},"g_ni_motozuite":{"f":"N + に基づいて","m":{"id":"Berdasarkan ...","en":"Based on"},"e":{"id":"Dasarnya berupa data, aturan, atau fakta. Bentuk penjelas kata benda: ～に基づく+N.","en":"The basis is data, rules or facts. Noun-modifying form: ～に基づく+N."},"x":[{"jp":"調査結果に基づいて、計画を立てた。","r":"ちょうさけっかにもとづいて、けいかくをたてた。","m":{"id":"Saya menyusun rencana berdasarkan hasil survei.","en":"We made the plan based on the survey results."}},{"jp":"事実に基づいた話です。","r":"じじつにもとづいたはなしです。","m":{"id":"Ini cerita yang berdasarkan fakta.","en":"This story is based on facts."}},{"jp":"法律に基づいて処理します。","r":"ほうりつにもとづいてしょりします。","m":{"id":"Akan ditangani berdasarkan hukum.","en":"It will be handled in accordance with the law."}}]},"g_wo_motte":{"f":"N + をもって","m":{"id":"Dengan ... / terhitung sejak atau sampai ... (formal)","en":"By means of / as of (formal)"},"e":{"id":"Dua pemakaian: sarana (～をもって応える) dan batas waktu resmi (本日をもって終了). Gaya sangat formal.","en":"Two uses: means (～をもって応える) and an official cut-off (本日をもって終了). Very formal."},"x":[{"jp":"本日をもって、営業を終了いたします。","r":"ほんじつをもって、えいぎょうをしゅうりょういたします。","m":{"id":"Terhitung hari ini, kami menghentikan operasional.","en":"As of today, we will cease operations."}},{"jp":"誠意をもって対応いたします。","r":"せいいをもってたいおういたします。","m":{"id":"Kami akan menanggapi dengan tulus.","en":"We will respond in good faith."}},{"jp":"これをもって、会議を終わります。","r":"これをもって、かいぎをおわります。","m":{"id":"Dengan ini rapat saya akhiri.","en":"With this, the meeting is adjourned."}}]},"g_naradeha":{"f":"N + ならでは","m":{"id":"Khas ... / hanya bisa ada pada ...","en":"Unique to / only possible with"},"e":{"id":"Memuji keunikan yang hanya dimiliki N. Sering dalam bentuk ならではの + N.","en":"Praises a quality only N has. Often in the form ならではの + N."},"x":[{"jp":"これは京都ならではの味です。","r":"これはきょうとならではのあじです。","m":{"id":"Ini rasa khas Kyoto.","en":"This is a flavor unique to Kyoto."}},{"jp":"プロならではの技術に感動した。","r":"プロならではのぎじゅつにかんどうした。","m":{"id":"Saya terkesan pada teknik khas profesional.","en":"I was moved by the skill only a pro has."}},{"jp":"手作りならではの温かさがある。","r":"てづくりならではのあたたかさがある。","m":{"id":"Ada kehangatan khas buatan tangan.","en":"It has a warmth only handmade things have."}}]},"g_zu_niwa_irarenai":{"f":"V-ない(語幹) + ずにはいられない","m":{"id":"Tidak bisa tidak ...","en":"Cannot help but"},"e":{"id":"Dorongan di luar kendali. Setara ～ないではいられない. する → せずにはいられない.","en":"An uncontrollable urge. Equivalent to ～ないではいられない. する → せずにはいられない."},"x":[{"jp":"おいしそうな匂いがして、食べずにはいられなかった。","r":"おいしそうなにおいがして、たべずにはいられなかった。","m":{"id":"Tercium bau lezat, saya tidak bisa tidak makan.","en":"It smelled so good I couldn't help eating."}},{"jp":"その話を聞いて、笑わずにはいられなかった。","r":"そのはなしをきいて、わらわずにはいられなかった。","m":{"id":"Mendengar cerita itu, saya tak bisa menahan tawa.","en":"I couldn't help laughing at that story."}},{"jp":"彼を見ていると、応援せずにはいられない。","r":"かれをみていると、おうえんせずにはいられない。","m":{"id":"Melihatnya, saya tidak bisa tidak mendukungnya.","en":"Watching him, I can't help but cheer him on."}}]},"g_te_yamanai":{"f":"V-て + やまない","m":{"id":"Terus (merasakan) ... tak henti","en":"Never ceases (feeling)"},"e":{"id":"Hanya dengan kata kerja perasaan atau harapan: 願う, 祈る, 愛する, 期待する. Gaya tulis atau formal.","en":"Only with verbs of feeling or hope: 願う, 祈る, 愛する, 期待する. Written or formal."},"x":[{"jp":"皆様のご健康を願ってやみません。","r":"みなさまのごけんこうをねがってやみません。","m":{"id":"Saya senantiasa mendoakan kesehatan Anda semua.","en":"I never cease to wish for everyone's health."}},{"jp":"彼の成功を期待してやまない。","r":"かれのせいこうをきたいしてやまない。","m":{"id":"Saya terus berharap kesuksesannya.","en":"I keep hoping for his success."}},{"jp":"故郷を愛してやまない。","r":"こきょうをあいしてやまない。","m":{"id":"Saya tak henti mencintai kampung halaman.","en":"I never stop loving my hometown."}}]},"g_wo_monotomosezu":{"f":"N + をものともせず","m":{"id":"Tak gentar menghadapi ...","en":"Undaunted by / in defiance of"},"e":{"id":"Memuji sikap yang tidak menghiraukan kesulitan besar.","en":"Praises someone who pays no heed to a major difficulty."},"x":[{"jp":"彼は反対をものともせず、計画を進めた。","r":"かれははんたいをものともせず、けいかくをすすめた。","m":{"id":"Tak peduli penolakan, dia melanjutkan rencana.","en":"Undaunted by opposition, he pushed ahead with the plan."}},{"jp":"選手は怪我をものともせず、最後まで走った。","r":"せんしゅはけがをものともせず、さいごまではしった。","m":{"id":"Pelari itu berlari sampai akhir meski cedera.","en":"The athlete ran to the end despite the injury."}},{"jp":"嵐をものともせず、船は出航した。","r":"あらしをものともせず、ふねはしゅっこうした。","m":{"id":"Kapal berlayar tanpa gentar pada badai.","en":"The ship set sail in defiance of the storm."}}]},"g_to_iedomo":{"f":"N／普通形 + といえども","m":{"id":"Sekalipun ...","en":"Even if / even though (literary)"},"e":{"id":"Gaya sastra atau tulis: 'sekalipun X, tetap ...'.","en":"Literary or written: 'even if X, still ...'."},"x":[{"jp":"専門家といえども、間違えることはある。","r":"せんもんかといえども、まちがえることはある。","m":{"id":"Sekalipun ahli, bisa saja salah.","en":"Even experts make mistakes."}},{"jp":"子どもといえども、責任がある。","r":"こどもといえども、せきにんがある。","m":{"id":"Sekalipun anak-anak, tetap ada tanggung jawab.","en":"Even a child bears responsibility."}},{"jp":"いかに優秀といえども、一人ではできない。","r":"いかにゆうしゅうといえども、ひとりではできない。","m":{"id":"Sehebat apa pun, sendirian tidak akan bisa.","en":"No matter how talented, one can't do it alone."}}]},"g_nbakari":{"f":"V-ない + んばかりに","m":{"id":"Seakan-akan hendak ...","en":"As if about to"},"e":{"id":"V-ない → ん + ばかり: menggambarkan keadaan yang nyaris terjadi. する → せんばかり.","en":"V-ない → ん + ばかり: describes a state that is nearly happening. する → せんばかり."},"x":[{"jp":"彼は泣かんばかりに喜んだ。","r":"かれはなかんばかりによろこんだ。","m":{"id":"Dia gembira sampai nyaris menangis.","en":"He was so happy he nearly cried."}},{"jp":"観客は割れんばかりの拍手を送った。","r":"かんきゃくはわれんばかりのはくしゅをおくった。","m":{"id":"Penonton memberi tepuk tangan yang menggelegar.","en":"The audience gave thunderous applause."}},{"jp":"彼女は今にも倒れんばかりの様子だった。","r":"かのじょはいまにもたおれんばかりのようすだった。","m":{"id":"Dia tampak hampir ambruk.","en":"She looked as if about to collapse."}}]},"g_katawara":{"f":"N／V-辞書形 + かたわら","m":{"id":"Di samping ... juga ...","en":"While also (alongside the main activity)"},"e":{"id":"Pekerjaan atau kegiatan utama, ditambah kegiatan lain yang terus berjalan.","en":"A main job or activity, plus another that continues alongside it."},"x":[{"jp":"彼は会社に勤めるかたわら、小説を書いている。","r":"かれはかいしゃにつとめるかたわら、しょうせつをかいている。","m":{"id":"Di samping bekerja di perusahaan, dia menulis novel.","en":"While working at a company, he also writes novels."}},{"jp":"母は主婦のかたわら、ボランティアをしている。","r":"はははしゅふのかたわら、ボランティアをしている。","m":{"id":"Selain jadi ibu rumah tangga, ibu juga jadi relawan.","en":"Besides being a housewife, my mother volunteers."}},{"jp":"学業のかたわら、アルバイトもした。","r":"がくぎょうのかたわら、アルバイトもした。","m":{"id":"Di samping kuliah, saya juga kerja paruh waktu.","en":"Alongside my studies, I also worked part-time."}}]},"g_yoginaku":{"f":"N + を余儀なくされる","m":{"id":"Terpaksa harus ... (karena keadaan)","en":"Forced to / have no alternative"},"e":{"id":"Keadaan di luar kehendak memaksa suatu langkah. Dipakai dalam bentuk pasif ～を余儀なくされる.","en":"Circumstances beyond one's will force an action. Used in the passive form ～を余儀なくされる."},"x":[{"jp":"不況で、会社は倒産を余儀なくされた。","r":"ふきょうで、かいしゃはとうさんをよぎなくされた。","m":{"id":"Karena resesi, perusahaan terpaksa bangkrut.","en":"Due to the recession, the company was forced into bankruptcy."}},{"jp":"彼は病気のため、引退を余儀なくされた。","r":"かれはびょうきのため、いんたいをよぎなくされた。","m":{"id":"Karena sakit, dia terpaksa pensiun.","en":"Because of illness, he was forced to retire."}},{"jp":"大雪で、予定の変更を余儀なくされた。","r":"おおゆきで、よていのへんこうをよぎなくされた。","m":{"id":"Karena salju lebat, jadwal terpaksa diubah.","en":"Heavy snow forced a change of plans."}}]},"g_tomonaru":{"f":"N + ともなると／ともなれば","m":{"id":"Kalau sudah sampai ... (tentu ...)","en":"When it comes to / once it becomes"},"e":{"id":"Menyatakan bahwa pada tahap atau status tertentu, hasil yang wajar pun berbeda.","en":"States that at a certain stage or status, a natural and different result follows."},"x":[{"jp":"社長ともなると、忙しさが違う。","r":"しゃちょうともなると、いそがしさがちがう。","m":{"id":"Kalau sudah jadi direktur, kesibukannya lain.","en":"Once you're a president, the busyness is on another level."}},{"jp":"三年生ともなれば、進路を真剣に考える。","r":"さんねんせいともなれば、しんろをしんけんにかんがえる。","m":{"id":"Kalau sudah kelas tiga, orang serius memikirkan masa depan.","en":"By third year, students think seriously about their future."}},{"jp":"夏休みともなると、海は人でいっぱいだ。","r":"なつやすみともなると、うみはひとでいっぱいだ。","m":{"id":"Kalau sudah libur musim panas, pantai penuh orang.","en":"Once summer vacation comes, the beach is packed."}}]},"g_kiwamarinai":{"f":"な-adj語幹／い-adj辞書形 + 極まりない","m":{"id":"Sangat ... sekali (biasanya bernada negatif)","en":"Extremely / utterly"},"e":{"id":"Sering dengan kata bernada negatif: 失礼, 危険, 迷惑. Dipasang pada akar な-adj atau bentuk kamus い-adj.","en":"Often with negative words: 失礼, 危険, 迷惑. Attach to a な-adjective stem or い-adjective dictionary form."},"x":[{"jp":"その態度は失礼極まりない。","r":"そのたいどはしつれいきわまりない。","m":{"id":"Sikap itu sangat tidak sopan.","en":"That attitude is utterly rude."}},{"jp":"夜の山道は危険極まりない。","r":"よるのやまみちはきけんきわまりない。","m":{"id":"Jalan gunung malam hari sangat berbahaya.","en":"The mountain road at night is extremely dangerous."}},{"jp":"こんなやり方は迷惑極まりない。","r":"こんなやりかたはめいわくきわまりない。","m":{"id":"Cara begini benar-benar merepotkan.","en":"This approach is utterly inconvenient."}}]},"g_ni_taru":{"f":"N／V-辞書形 + に足る","m":{"id":"Layak / pantas ...","en":"Worthy of"},"e":{"id":"Untuk hal yang layak dipercaya, dihormati, dan sebagainya. Negatif: に足りない 'tidak layak'.","en":"For things worth trusting, respecting and so on. Negative: に足りない 'not worth'."},"x":[{"jp":"彼は信頼するに足る人物だ。","r":"かれはしんらいするにたるじんぶつだ。","m":{"id":"Dia orang yang layak dipercaya.","en":"He is a person worthy of trust."}},{"jp":"この作品は賞賛に足る。","r":"このさくひんはしょうさんにたる。","m":{"id":"Karya ini layak dipuji.","en":"This work deserves praise."}},{"jp":"取るに足りない問題だ。","r":"とるにたりないもんだいだ。","m":{"id":"Ini masalah sepele yang tidak perlu diperhatikan.","en":"It's a trivial problem not worth bothering with."}}]},"g_tari_tomo":{"f":"一 + 助数詞 + たりとも + 否定","m":{"id":"Satu pun tidak ...","en":"Not even one / not a single"},"e":{"id":"Selalu dengan bentuk negatif: 一秒たりとも, 一円たりとも. Nadanya tegas dan penuh tekad.","en":"Always with a negative: 一秒たりとも, 一円たりとも. Firm and resolute in tone."},"x":[{"jp":"一円たりとも無駄にできない。","r":"いちえんたりともむだにできない。","m":{"id":"Satu yen pun tidak boleh disia-siakan.","en":"I can't waste even a single yen."}},{"jp":"一瞬たりとも気を抜いてはいけない。","r":"いっしゅんたりともきをぬいてはいけない。","m":{"id":"Tidak boleh lengah sedetik pun.","en":"You mustn't let your guard down for even a moment."}},{"jp":"約束は一日たりとも遅れてはならない。","r":"やくそくはいちにちたりともおくれてはならない。","m":{"id":"Janji tidak boleh terlambat sehari pun.","en":"The deadline can't slip by even a single day."}}]},"g_yuenni":{"f":"N／普通形 + ゆえに","m":{"id":"Karena ... (gaya sastra)","en":"Because of (literary)"},"e":{"id":"Gaya tulis atau sastra, setara から/ので. Kata benda: N の + ゆえ(に).","en":"Written or literary, equivalent to から/ので. Nouns: N の + ゆえ(に)."},"x":[{"jp":"貧しさゆえに、学校に行けなかった。","r":"まずしさゆえに、がっこうにいけなかった。","m":{"id":"Karena kemiskinan, dia tidak bisa sekolah.","en":"Because of poverty, he couldn't go to school."}},{"jp":"彼は若さゆえの過ちを犯した。","r":"かれはわかさゆえのあやまちをおかした。","m":{"id":"Dia berbuat salah karena masih muda.","en":"He made a mistake born of youth."}},{"jp":"有名ゆえに、苦労も多い。","r":"ゆうめいゆえに、くろうもおおい。","m":{"id":"Karena terkenal, kesulitannya pun banyak.","en":"Being famous, he has many hardships too."}}]},"g_kinjienai":{"f":"N／V + を禁じ得ない","m":{"id":"Tak dapat menahan (perasaan)","en":"Cannot suppress (an emotion)"},"e":{"id":"Dipakai dengan perasaan: 涙, 怒り, 驚き, 同情. Gaya formal.","en":"Used with emotions: 涙, 怒り, 驚き, 同情. Formal."},"x":[{"jp":"彼の死に、悲しみを禁じ得ない。","r":"かれのしに、かなしみをきんじえない。","m":{"id":"Saya tidak dapat menahan kesedihan atas kematiannya.","en":"I can't suppress my sorrow at his death."}},{"jp":"不正の事実に、怒りを禁じ得ません。","r":"ふせいのじじつに、いかりをきんじえません。","m":{"id":"Saya tak dapat menahan amarah atas fakta kecurangan itu.","en":"I cannot suppress my anger at the fact of misconduct."}},{"jp":"その話を聞いて、涙を禁じ得なかった。","r":"そのはなしをきいて、なみだをきんじえなかった。","m":{"id":"Mendengar cerita itu, saya tak dapat menahan air mata.","en":"Hearing that story, I couldn't hold back tears."}}]}};
